def svg(name: str, size: int = 18, color: str = "currentColor", stroke_width: float = 2, cls: str = "") -> str:
    body = ICONS.get(name, ICONS["circle-alert"])
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" '
        f'stroke="{color}" stroke-width="{stroke_width}" stroke-linecap="round" stroke-linejoin="round" '
        f'class="lucide {cls}" aria-hidden="true">{body}</svg>'
    )


def data_uri(name: str) -> str:
    """URL-encoded data URI for use as a CSS mask-image."""
    raw = svg(name, 24, "black")
    return "data:image/svg+xml;utf8," + quote(raw, safe="")
